-- Model cost shares add up to the whole dbt bill.
{{ config(tags=['contract', 'contract_finance'], severity='error',
          meta={'contract': 'finance', 'rule': 'F-10'}) }}

with contract_side as (
    select sum(pct_of_dbt_cost) as value from {{ ref('mart_cost_by_model') }}
),
reference_side as (
    select 100 as value
)
select c.value as contract_value, r.value as reference_value
from contract_side c cross join reference_side r
where c.value is null or r.value is null or abs(c.value - r.value) > 0.5
